{
  "name": "pi-opencode-go-provider",
  "version": "1.1.57",
  "description": "Opencode Go provider extension for pi - Fast, efficient GLM, Kimi, and MiniMax models through the opencode.ai API",
  "type": "module",
  "main": "index.ts",
  "scripts": {
    "clean": "echo 'nothing to clean'",
    "build": "echo 'nothing to build'",
    "check": "npm run typecheck && npm run test && node scripts/test-pi-compat.mjs",
    "update-models": "node scripts/update-models.js",
    "test": "node --test 'tests/!(sync-policy|quiet-startup-sync|usage-sync).test.ts' && vitest run",
    "typecheck": "tsc --noEmit && tsc --noEmit -p tsconfig.vitest.json",
    "test:pi": "node scripts/test-pi-compat.mjs"
  },
  "keywords": [
    "pi",
    "extension",
    "provider",
    "opencode",
    "opencode-go",
    "ai",
    "llm",
    "glm",
    "kimi",
    "minimax"
  ],
  "author": "",
  "license": "MIT",
  "pi": {
    "extensions": [
      "./index.ts"
    ]
  },
  "overrides": {
    "brace-expansion": "5.0.12"
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "1.5.0",
    "@types/node": "~22.19.0",
    "typescript": "^6.0.3",
    "vitest": "4.1.7"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/monotykamary/pi-opencode-go-provider.git"
  }
}
